<div class="table-wrap"><table><thead><tr><th>Request</th><?php if((string)session()->get('role')!=='borrower'): ?><th>Borrower</th><?php endif; ?><th>Purpose</th><th>Dates</th><th>Items</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($requests as $r): ?><tr><td><b><?= esc($r['request_number']) ?></b><small><?= esc(fmt_date($r['created_at'],true)) ?></small></td><?php if((string)session()->get('role')!=='borrower'): ?><td><?= esc($r['borrower_name']) ?></td><?php endif; ?><td class="truncate-cell"><?= esc($r['purpose']) ?></td><td><?= esc(fmt_date($r['requested_date'])) ?><small>Return: <?= esc(fmt_date($r['expected_return_date'])) ?></small></td><td><?= (int)$r['item_count'] ?> item(s)<small><?= (int)$r['requested_units'] ?> units</small></td><td><?= view('partials/status_badge',['status'=>$r['status']]) ?></td><td><a class="btn small" href="<?= site_url('borrow-requests/'.$r['id']) ?>">View</a></td></tr><?php endforeach; ?><?php if(empty($requests)): ?><tr><td colspan="7"><div class="empty">No borrowing requests found.</div></td></tr><?php endif; ?></tbody></table></div>
